import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const NODES = ['n0', 'n1', 'n2'];
const views = async (h) => Promise.all(NODES.map((n) => h.node(n)));

test('fresh system', async () => {
  const h = await createHost();
  for (const v of await views(h)) assert.deepEqual(v, { role: 'follower', term: 0, votedFor: null, leader: null });
  assert.equal(await h.node('n3'), null);
  assert.deepEqual(await h.inFlight(), []);
  const r = await h.timeout('x');
  assert.equal(r.ok, false);
});

test('timeout makes a candidate and sends RequestVote', async () => {
  const h = await createHost();
  assert.deepEqual(await h.timeout('n0'), { ok: true });
  assert.deepEqual(await h.node('n0'), { role: 'candidate', term: 1, votedFor: 'n0', leader: null });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  for (const m of msgs) {
    assert.equal(m.from, 'n0');
    assert.equal(m.action, 'RequestVote');
    assert.deepEqual(m.data, { from: 'n0', term: 1 });
  }
  assert.deepEqual(msgs.map((m) => m.to).sort(), ['n1', 'n2']);
  assert.equal((await h.timeout('n0')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0', leader: 'n0' });
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n0', leader: 'n0' });
  assert.equal((await h.timeout('n1')).ok, false);
});

test('one by one: vote reply', async () => {
  const h = await createHost();
  await h.timeout('n0');
  const [m] = (await h.inFlight()).filter((x) => x.to === 'n1');
  await h.deliver(m.id);
  const reply = (await h.inFlight()).find((x) => x.action === 'VoteReply');
  assert.deepEqual({ from: reply.from, to: reply.to, data: reply.data }, { from: 'n1', to: 'n0', data: { term: 1, granted: true } });
  await h.deliver(reply.id);
  assert.equal((await h.node('n0')).role, 'leader');
  // n2 has not heard RequestVote yet; the Leader announcement moves it to term 1 without a vote.
  const ann = (await h.inFlight()).filter((x) => x.action === 'Leader');
  assert.deepEqual(ann.map((x) => x.to).sort(), ['n1', 'n2']);
  for (const a of ann) assert.deepEqual({ from: a.from, data: a.data }, { from: 'n0', data: { from: 'n0', term: 1 } });
  await h.deliver(ann.find((x) => x.to === 'n2').id);
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: null, leader: 'n0' });
  await h.deliverAll();
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: 'n0', leader: 'n0' });
});

test('a candidate steps down on Leader and keeps its vote', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.timeout('n2');
  const toN1 = (await h.inFlight()).find((x) => x.to === 'n1' && x.from === 'n0');
  await h.deliver(toN1.id);
  await h.deliver((await h.inFlight()).find((x) => x.action === 'VoteReply').id);
  assert.equal((await h.node('n0')).role, 'leader');
  await h.deliver((await h.inFlight()).find((x) => x.action === 'Leader' && x.to === 'n2').id);
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: 'n2', leader: 'n0' });
  await h.deliverAll();
  const vs = await views(h);
  assert.equal(vs.filter((v) => v.role === 'leader').length, 1);
  for (const v of vs) assert.equal(v.leader, 'n0');
});

test('all three time out: at most one leader, any order', async () => {
  for (let seed = 1; seed <= 30; seed++) {
    let s = seed;
    const rnd = () => ((s = (s * 1103515245 + 12345) % 2147483648) / 2147483648);
    const h = await createHost();
    for (const n of NODES) assert.deepEqual(await h.timeout(n), { ok: true });
    for (;;) {
      const msgs = await h.inFlight();
      if (!msgs.length) break;
      await h.deliver(msgs[Math.floor(rnd() * msgs.length)].id);
    }
    const vs = await views(h);
    const leaders = vs.filter((v) => v.role === 'leader');
    assert.ok(leaders.length <= 1);
    if (leaders.length) for (const v of vs) assert.equal(v.leader, NODES[vs.indexOf(leaders[0])]);
    else for (const v of vs) assert.equal(v.leader, null);
    for (const v of vs) assert.equal(v.votedFor, NODES[vs.indexOf(v)]);
    h.__dispose?.();
  }
});

